int characterReplacement(String s, int k) {
    int[] count = new int[26];
    int l = 0, maxCount = 0, best = 0;
    for (int r = 0; r < s.length(); r++) {
        maxCount = Math.max(maxCount, ++count[s.charAt(r) - 'A']);
        if (r - l + 1 - maxCount > k) {
            count[s.charAt(l) - 'A']--;
            l++;
        }
        best = Math.max(best, r - l + 1);
    }
    return best;
}

